-- v100: 英语题库补充 — 对口升学考纲题型全覆盖
INSERT IGNORE INTO question_bank (subject, question_type, question_text, options, correct_answer, explanation, difficulty_level, status) VALUES
-- ═══ 语法选择（15题） ═══
('英语[职高]','SINGLE_CHOICE','I _____ to school by bus every day.','["A. go","B. goes","C. went","D. going"]','A','一般现在时，主语I用动词原形go。',1,1),
('英语[职高]','SINGLE_CHOICE','She _____ breakfast at 7:00 yesterday.','["A. have","B. has","C. had","D. having"]','C','yesterday表示过去，用一般过去时had。',1,1),
('英语[职高]','SINGLE_CHOICE','We _____ this movie before.','["A. see","B. saw","C. have seen","D. will see"]','C','before用于现在完成时。',2,1),
('英语[职高]','SINGLE_CHOICE','They _____ a new hospital next year.','["A. build","B. built","C. are building","D. will build"]','D','next year将来时。',1,1),
('英语[职高]','SINGLE_CHOICE','Listen! Someone _____ the piano.','["A. plays","B. is playing","C. played","D. has played"]','B','Listen!提示进行时。',2,1),
('英语[职高]','SINGLE_CHOICE','The bridge _____ last year.','["A. builds","B. built","C. was built","D. is built"]','C','被动语态+一般过去时。',2,1),
('英语[职高]','SINGLE_CHOICE','English _____ in many countries.','["A. speaks","B. is spoken","C. spoke","D. is speaking"]','B','被动语态is spoken。',2,1),
('英语[职高]','SINGLE_CHOICE','He wants _____ an engineer.','["A. become","B. became","C. to become","D. becoming"]','C','want to do sth。',1,1),
('英语[职高]','SINGLE_CHOICE','I enjoy _____ books.','["A. read","B. reads","C. to read","D. reading"]','D','enjoy doing sth。',2,1),
('英语[职高]','SINGLE_CHOICE','The girl _____ is over there is my sister.','["A. who","B. which","C. what","D. whose"]','A','定语从句指人用who。',2,1),
('英语[职高]','SINGLE_CHOICE','I don''t know _____ he will come.','["A. if","B. that","C. what","D. which"]','A','宾语从句表示"是否"用if。',2,1),
('英语[职高]','SINGLE_CHOICE','He was tired _____ he kept working.','["A. and","B. so","C. but","D. or"]','C','转折关系用but。',1,1),
('英语[职高]','SINGLE_CHOICE','You _____ return the book on time.','["A. can","B. may","C. must","D. need"]','C','must表示必须。',1,1),
('英语[职高]','SINGLE_CHOICE','_____ beautiful the flowers are!','["A. What","B. What a","C. How","D. How a"]','C','How+adj.感叹句。',2,1),
('英语[职高]','SINGLE_CHOICE','The book _____ I borrowed is interesting.','["A. who","B. which","C. what","D. whose"]','B','定语从句指物用which。',2,1),

-- ═══ 情景交际（10题） ═══
('英语[职高]','SINGLE_CHOICE','— Thank you! — _____.','["A. No thanks","B. You''re welcome","C. Yes please","D. That''s right"]','B','感谢的回答。',1,1),
('英语[职高]','SINGLE_CHOICE','— I''m sorry. — _____.','["A. That''s all right","B. That''s right","C. I think so","D. I''d love to"]','A','道歉的回答。',1,1),
('英语[职高]','SINGLE_CHOICE','— Could you help me? — _____.','["A. Yes please","B. With pleasure","C. Never mind","D. Not at all"]','B','回应请求。',2,1),
('英语[职高]','SINGLE_CHOICE','— Would you like some coffee? — _____.','["A. Yes, I like","B. No, I don''t","C. Yes, please","D. Yes, I would"]','C','接受提供。',1,1),
('英语[职高]','SINGLE_CHOICE','— How is the weather? — _____.','["A. It''s sunny","B. I like it","C. Yes, it is","D. That''s good"]','A','问天气。',1,1),
('英语[职高]','SINGLE_CHOICE','— What day is today? — _____.','["A. June 1st","B. Monday","C. 8 o''clock","D. Fine"]','B','问星期。',1,1),
('英语[职高]','SINGLE_CHOICE','— What''s the date? — _____.','["A. Tuesday","B. May 20","C. 2026","D. Rainy"]','B','问日期。',2,1),
('英语[职高]','SINGLE_CHOICE','— How much is it? — _____.','["A. Very good","B. 20 yuan","C. Interesting","D. Mine"]','B','问价格。',1,1),
('英语[职高]','SINGLE_CHOICE','— May I use your pen? — _____.','["A. Sure","B. Yes I do","C. No you may not","D. That''s right"]','A','借东西。',1,1),
('英语[职高]','SINGLE_CHOICE','— Let''s go swimming. — _____.','["A. Good idea","B. Thanks","C. Yes I do","D. That''s right"]','A','赞同建议。',1,1),

-- ═══ 词汇辨析（10题） ═══
('英语[职高]','SINGLE_CHOICE','It _____ me 30 minutes to get to school.','["A. spends","B. takes","C. costs","D. pays"]','B','it takes sb time to do。',2,1),
('英语[职高]','SINGLE_CHOICE','The shirt _____ me 120 yuan.','["A. spent","B. took","C. cost","D. paid"]','C','物+cost+人+钱。',2,1),
('英语[职高]','SINGLE_CHOICE','My mother _____ she is busy.','["A. speaks","B. talks","C. says","D. tells"]','C','say+从句。',2,1),
('英语[职高]','SINGLE_CHOICE','Please _____ the light when leaving.','["A. turn on","B. turn off","C. turn up","D. turn down"]','B','关灯用turn off。',1,1),
('英语[职高]','SINGLE_CHOICE','Can you _____ after your sister?','["A. look for","B. look at","C. look after","D. look up"]','C','照顾用look after。',1,1),
('英语[职高]','SINGLE_CHOICE','I''m _____ in collecting stamps.','["A. interest","B. interested","C. interesting","D. interests"]','B','be interested in。',2,1),
('英语[职高]','SINGLE_CHOICE','She was so _____ that she couldn''t speak.','["A. excite","B. excited","C. exciting","D. excitement"]','B','excited修饰人。',2,1),
('英语[职高]','SINGLE_CHOICE','I _____ you to pass the exam.','["A. hope","B. wish","C. want","D. expect"]','B','wish sb to do。',3,1),
('英语[职高]','SINGLE_CHOICE','He is good _____ basketball.','["A. at","B. in","C. for","D. with"]','A','be good at。',1,1),
('英语[职高]','SINGLE_CHOICE','She took the wrong train _____.','["A. by mistake","B. by accident","C. by heart","D. by hand"]','A','by mistake错误地。',3,1);
